  let showVps = true, showLabels = true, showRailways = true, showSupplyHubs = true, showAdjacency = true;
  let panelMinimized = false;       // info panel collapsed to a small "Panel" button
  let provinceToOwner = {};         // province id -> owner tag (mutable; edits update this)
  let countryColors = {};           // TAG -> [r,g,b] from colors.txt (real in-game colors)
  let baseImageData = null;         // source provinces.bmp pixels (with unsaved paint applied)
  let baseImageDataPristine = null; // the on-disk-baseline pixels (no unsaved paint) — so Undo can rebuild
  let ownerCanvas = null;           // offscreen, owner-coloured
  let imgW = 0, imgH = 0;
  let provinceCentroid = new Map(); // province id -> {x,y} (avg pixel position) for VP markers/labels
  let stateCentroid = new Map();    // state id -> {x,y}
  let mode = "inspect";             // inspect | paint | move | mergestate
  let selected = null;              // { provinceId, stateId }
  // Declared here, not beside the functions that use them: updateSaveButton() sits above those and now
  // reads stateFormBaseline, and a `let` throws for anything that reaches it before its own line runs.
  let stateFormBaseline = null;     // { stateId, provinceId, sig, shown } — null until the panel is first filled
  let stagingStateForm = false;     // stageStateWrite ends in a repaint; never re-enter
  let multiSelect = new Set();      // Inspect mode: shift-click builds a set of state ids for bulk edits
  let adjFirst = null;              // Adjacency mode: province id of the first click (awaiting the second)
  let railPath = [];               // Railway mode: the province chain being drawn (committed on Finish)
  let marquee = null;              // Inspect shift+drag: rubber-band rectangle {x0,y0,x1,y1} in canvas coords
  let moveSource = null;            // move mode: first-clicked { provinceId, stateId }
  let moveTarget = null;            // "fill" mode: a state id (e.g. a brand-new empty one) that each
                                    // clicked province is added to directly — a new state has no
                                    // provinces to click as a destination, so the normal two-click
                                    // move can't fill it. Set by New state; cleared on any mode change.
  let mergeSource = null;           // mergestate mode: the state id being merged away
  let brush = null;                 // paintshape: { r,g,b, provinceId, ownerColor }
  let painting = false;             // paintshape: mouse down + painting
  let paintDiff = new Map();        // "x,y" -> {x,y,r,g,b} pending painted pixels
  let brushRadius = 2;              // image-pixel brush radius (set by the Brush size control)
  let lastMouseX = null, lastMouseY = null, brushCursorEl = null; // Paint-shape brush-circle cursor state
  let scale = 1, offX = 0, offY = 0;
  let measureA = null, measureB = null; // ruler tool endpoints, in IMAGE pixel coords ({x,y})

  // ── Deferred saving ──────────────────────────────────────────────────────────────────────────
