    const sum = (xs, f) => xs.reduce((a, x) => a + (Number(f(x)) || 0), 0), list = (xs, f) => `${xs.slice(0, 8).map(f).join("; ")}${xs.length > 8 ? "; …" : ""}`;
    // ⛔ #a-moved-capital-is-named (tool campaign B2-9, the 09-05 audit's #32) — which country, from which state to which: the answer carries all three,
    // and the line said only a count, so the modder could not tell whose capital moved (on a vanilla add-on, a whole country history copied in for it)
    const moved = d.filter((x) => x && x.tag && x.to != null);
