    const kept = c.kept || [], gone = c.stillGone || [], caps = c.capitals || {};
    const names = (list) => list.slice(0, 6).join(", ") + (list.length > 6 ? `, … (${list.length} in all)` : "");
    let out = "";
    if (kept.length) {
      const who = kept.map((k) => (k.from ? `${k.tag} from ${k.from}` : k.tag));
      out += ` ${kept.length} countr${kept.length === 1 ? "y" : "ies"} whose land stayed under the sea took the new state nearest ${kept.length === 1 ? "it" : "them"} (${names(who)}; for a country whose land had a coast, the nearest on the ocean when one is at most a few steps farther), so every country of the world underneath is on this map.`;
      // a country that exists loads its order of battle, and theirs stands on the drowned land: over vanilla (10-07) the 30 kept
      // start 664 divisions and 18 task forces there, and Auto-fix's moves copy 65 more base-game unit files into the mod. Said, not hidden.
      out += ` Any army or fleet ${kept.length === 1 ? "it starts" : "they start"} the game with still starts on that old land, under the sea: Auto-fix moves the armies onto ${kept.length === 1 ? "its" : "their"} new land and the fleets to a harbour or out to sea, and copies each base-game order-of-battle file it changes into your mod to do it.`;
    }
