  function blankAdjacencyNote(adj) {
    if (!adj || !adj.rows) return "";
    const t = adj.byType || {};
    const count = (n, one, many) => `${n} ${n === 1 ? one : many}`;
    const bits = [];
    if (t.impassable) bits.push(count(t.impassable, "impassable border", "impassable borders"));
    if (t.sea) bits.push(count(t.sea, "strait or canal", "straits or canals"));
    const other = adj.rows - (t.impassable || 0) - (t.sea || 0);
    if (other > 0) bits.push(count(other, "other link", "other links"));
    const what = `${count(adj.rows, "row", "rows")} in map/adjacencies.csv (${bits.join(", ")}) still ${adj.rows === 1 ? "names" : "name"} a province that is now sea.`;
    return adj.own
      ? `${what} They are in your mod's own file and Nova left every one exactly as it was — what HOI4 does with a link over open water is not established, so remove or redraw them in 🔗 Adjacency mode as you build the new land.`
      : `${what} They come from the base game or a dependency, so Nova did not change them and they still load underneath your mod; a map/adjacencies.csv of your own replaces that whole file.`;
  }
