    if (rv.skipped) return `Your rivers were left alone: ${rv.skipped}. Rivers over water are drawn in-game but flow nowhere — check map/rivers.bmp once the map says what you mean.`;
    if (!rv.changed || !rv.cleared) return "";
    const n = Number(rv.cleared || 0).toLocaleString();
    const cleared = (rv.created ? "Your mod now has its own map/rivers.bmp: " : "")
      + `${n} river pixel${rv.cleared === 1 ? "" : "s"} were cleared, because every one of them was left running across land that is now sea.`;
    if (opts && opts.world) return cleared;
