      const to = new Map(waterBack.filter((x) => x.state === st && x.to).map((x) => [x.province, x.to])), groups = new Map();
      for (const p of st.provinces || []) if (to.has(p)) groups.set(to.get(p), (groups.get(to.get(p)) || []).concat([p]));
