  const riverWidthT = (c) => { if (c.r >= 128) return 0; return Math.max(0, Math.min(1, (255 - c.g) / 255 * 0.6 + (255 - c.b) / 255)); };
  const riverWaterCss = (c) => { const t = riverWidthT(c), L = { r: 74, g: 156, b: 226 }, D = { r: 22, g: 82, b: 188 }, m = (a, b) => Math.round(a + (b - a) * t); return `rgb(${m(L.r, D.r)},${m(L.g, D.g)},${m(L.b, D.b)})`; };
