    const items = [];
    const near = (c, r, g, b, tol) => !!c && Math.abs(c.r - r) <= (tol == null ? 30 : tol) && Math.abs(c.g - g) <= (tol == null ? 30 : tol) && Math.abs(c.b - b) <= (tol == null ? 30 : tol);
    const idxOf = (pred) => { for (let i = 0; i < pal.length; i++) if (pred(pal[i], i)) return i; return -1; };
