    // the white sea). Fall back to a green land only for synthetic test bitmaps that have no grey.
    let eraseIdx = idxOf((c) => c && riverGrey(c) && c.r > 40 && c.r < 210);
    if (eraseIdx < 0) eraseIdx = idxOf((c) => c && c.r === 0 && c.g === 255 && c.b === 0);
    if (eraseIdx >= 0) { const c = pal[eraseIdx]; items.push({ i: eraseIdx, role: "erase", label: "🧹 Erase", sw: `rgb(${c.r},${c.g},${c.b})`, tip: `Erase — paint land to remove a river (palette ${eraseIdx}).` }); }
    // The three markers, by their exact documented colours. (Skip green-as-source if green was used as land.)
    const srcIdx = idxOf((c) => near(c, 0, 255, 0));
    if (srcIdx >= 0 && srcIdx !== eraseIdx) items.push({ i: srcIdx, role: "source", label: "🟢 Source", sw: "rgb(0,205,0)", tip: `River SOURCE — where a river begins. Every river needs exactly ONE source pixel (palette ${srcIdx}).` });
    const inIdx = idxOf((c) => near(c, 255, 0, 0));
