    const outIdx = idxOf((c) => near(c, 255, 252, 0, 40));
    if (outIdx >= 0) items.push({ i: outIdx, role: "flowout", label: "🟡 Branches", sw: "rgb(225,200,0)", tip: `Flow-OUT — a river branches outward here (palette ${outIdx}).` });
