    larges.forEach((w, n) => { const giant = n === larges.length - 1; items.push({ i: w.i, role: "large", label: `Large ${n + 1}${giant ? " ▇ giant" : ""}`, sw: riverWaterCss(w.c), tip: `LARGE / major river — width ${n + 1} of ${larges.length}${giant ? " (the WIDEST — a giant river)" : ""}; big crossing penalty (palette ${w.i}).` }); });
