    // the countries are its own land's)
    const kb = ow.keptBelow || null;
    const fromWhere = kb && kb.ownMap ? "taken from your mod's own land (your mod draws its own map, so the province ids of the world underneath are other places in it)" : "taken from the world underneath";
    const owned = ow.mode === "inherit"
      ? ` Gave them to ${(ow.countries || 0).toLocaleString()} countr${ow.countries === 1 ? "y" : "ies"} ${fromWhere} — ${(ow.byMajority || 0).toLocaleString()} state${ow.byMajority === 1 ? "" : "s"} to whoever held most of its land, ${(ow.byProximity || 0).toLocaleString()} to its nearest neighbour${ow.undecided ? `, and ${ow.undecided.toLocaleString()} left with no owner (nothing below spoke for them)` : ""}.`
      : ow.mode === "none"
