    // …names Nova wrote that are out of date (a state renamed, a language a write missed), and lines of Nova's hiding yours
    if (s.namesStale) bits.push(`${pl(s.namesStale, "region name Nova wrote is", "region names Nova wrote are")} out of date — a state ${Number(s.namesStale) === 1 ? "it is" : "they are"} named after was renamed, or a language missed a write; the names file brings ${Number(s.namesStale) === 1 ? "it" : "them"} up to date.`);
    if (s.namesHidden) bits.push(`${pl(s.namesHidden, "name you gave a region in your own files is", "names you gave regions in your own files are")} hidden by a line in Nova's names file; ${Number(s.namesHidden) === 1 ? "that line is" : "those lines are"} removed, so yours show.`);
    const files = s.files || {};
    const what = [];
    if (files.regionFiles) what.push(`<b>${pl(files.regionFiles, "region file", "region files")}</b>${files.created ? ` (${n(files.created)} new)` : ""}`);
    if (files.weatherpositions !== false) what.push("map/weatherpositions.txt");
    if (s.lakesToSea) what.push("map/definition.csv and map/unitstacks.txt");
