    const keys = Object.keys(b.times).map(Number).filter(Number.isFinite);
    if (!keys.length) return "";
    const p = Number(pct) || 35;
    const near = keys.reduce((best, k) => (Math.abs(k - p) < Math.abs(best - p) ? k : best), keys[0]);
    const times = Number(b.times[near]) || 0;
    if (times < 2) return "";
