    if (key === "prepare" || key === "generate") return of(a.backups && a.backups.dir, Number(a.backups && a.backups.files) || 0);
    if (key === "blank") return of(a.snapshotPath, Math.max(Number(a.scopeCopied) || 0, (Number(a.snapshotted) || 0) + (Number(a.overwriteSnapshotted) || 0)) || (a.snapshotPath ? 1 : 0));
    if (key === "autofix" || key === "refix") { const b = (a.fixes && a.fixes.backupSnapshot) || {}; return of(b.dir, Number(b.files) || 0); }
    // Redraw names its scope's folder whenever it owned the scope; backupsCopied says whether the folder holds anything (or exists)
    if (key === "regions") { const w = a.write || {}; return of(typeof w.backups === "string" ? w.backups : "", typeof w.backupsCopied === "number" ? w.backupsCopied : w.backups ? 1 : 0); }
