        if (pc.resolved && pc.resolved.length) parts.push(`gave ${pc.resolved.length} province(s) claimed by two states a single owner${pc.deletedStates && pc.deletedStates.length ? ` (and removed ${pc.deletedStates.length} now-empty stub state(s))` : ""}`);
