        if (sg.renumbered && sg.renumbered.length) parts.push(`renumbered ${sg.renumbered.length} state(s) to close an id gap (state ids must run 1..max with no gap, or HOI4 refuses to load the map)${sg.residualFiles && sg.residualFiles.length ? ` — review ${sg.residualFiles.length} file(s) that still mention the old id` : ""}`);
        // (#an-add-on-is-told-what-auto-fix-froze: …and, on an add-on, that the file the ports went into is now the mod's — the first
        // building row a click writes copies the layer's whole map/buildings.txt in)
        if (cnp.added) parts.push(`gave ${cnp.added} newly-coastal province(s) a port (HOI4's own words for a coastal province with none, which only a launch started with -debug writes to error.log: “will likely crash the game”)` + materialisedNote(cnp.materialised));
        if (cnp.error) unfinished.push(`could not give the newly-coastal provinces a port: ${why(cnp.error)}`);
        // ⚓ #a-port-whose-water-became-land — the ports whose 7th column names no sea: land now, a lake, or no province at all.
        const spg = (fr.fixes && fr.fixes.strandedPorts) || {};
        if (spg.removed) parts.push(`removed ${spg.removed} port(s) from map/buildings.txt whose ships had no sea to lie in${(spg.provinces || []).length ? ` (facing province ${spg.provinces.slice(0, 8).join(", ")}${spg.provinces.length > 8 ? ", …" : ""})` : ""} — a port pointing at land crashed HOI4 a second after the menu`);
        if (spg.error) unfinished.push(`could not remove the ports whose sea is gone: ${why(spg.error)}`);
        // #the-coastal-column-is-derived — definition.csv's coastal column, recomputed from the bitmap.
        const cfl = (fr.fixes && fr.fixes.coastalFlags) || {};
        if (cfl.changed) parts.push(`corrected the coastal flag of ${cfl.changed} province(s) in map/definition.csv to what the map shows (HOI4 plays the bitmap's answer, and only a launch started with -debug writes each disagreement to error.log)`
          + (cfl.materialized ? ` — to do it, map/definition.csv is now YOUR mod's, frozen at this build of the map below` : ""));
        if (cfl.error) unfinished.push(`could not correct the coastal flags in map/definition.csv: ${why(cfl.error)}`);
        // #a-dockyard-with-no-coast — the naval buildings a state or province keeps with no sea left beside it.
        const nnc = (fr.fixes && fr.fixes.navalNoCoast) || {};
        // ⛔ #a-coast-taken-away-keeps-its-naval-buildings — what it moved with the coast, and what it left where it is: it deletes none
        const nncMoved = Array.isArray(nnc.moved) ? nnc.moved : [], nncCarried = Array.isArray(nnc.carried) ? nnc.carried : [], nncLeft = Array.isArray(nnc.left) ? nnc.left : [];
        // (⛔ #a-moved-naval-base-keeps-its-comments-and-its-dates — the coast-only buildings that went with a base, and those its new province's own kept behind)
        const coastWords = (keys) => keys.map((k) => String(k).replace(/_/g, " ")).join(", ");
        const withIt = (b) => ((b.with || []).length ? `, with its ${coastWords(b.with)}` : "");
        const stayedBehind = nncMoved.concat(...nncCarried.map((c) => c.navalBases || [])).filter((b) => (b.stayed || []).length);
        // (⛔ #the-harbour-words-say-what-auto-fix-did, B4-17 — the line claimed the base's province had lost its sea, said of a base typed on a province
        // that never had one, vanilla's inland 13069: the repair moves a base standing on a province with no sea beside it, whatever put it there)
        if (nncMoved.length) parts.push(`moved ${nncMoved.length} naval base(s) on a province with no sea beside it onto another coastal province of the same state, at the same level (${nncMoved.slice(0, 6).map((m) => `${m.from} → ${m.to} in state ${m.stateId}${withIt(m)}`).join(", ")}${nncMoved.length > 6 ? ", …" : ""})`);
        const carryWords = (list) => list.slice(0, 6).map((c) => `state ${c.from} → ${c.to}: ${(c.levels || []).map((l) => `${l.level} ${String(l.key).replace(/_/g, " ")}${Number(l.level) === 1 ? "" : "s"}${l.date ? ` from ${l.date}` : ""}`).concat((c.navalBases || []).map((b) => `the level-${b.level} naval base of ${b.from} onto ${b.to}${b.state != null && b.state !== c.to ? ` in state ${b.state}` : ""}${withIt(b)}`)).join(", ")}`).join("; ") + (list.length > 6 ? "; …" : "");
        const nncGone = nncCarried.filter((c) => !c.keptCoast), nncFull = nncCarried.filter((c) => c.keptCoast);
        if (nncGone.length) parts.push(`moved the dockyards and naval bases of ${nncGone.length} state(s) left with no coast to the nearest coastal state of the same country (${carryWords(nncGone)}) — HOI4 keeps no dockyard in a state with no coast`);
        if (nncFull.length) parts.push(`moved the naval bases of ${nncFull.length} state(s) with no coastal province free for them to the nearest coastal state of the same country that has one (${carryWords(nncFull)})`);
        if (stayedBehind.length) unfinished.push(`left ${stayedBehind.slice(0, 6).map((b) => `the ${coastWords(b.stayed)} on province ${b.from}`).join(", ")}${stayedBehind.length > 6 ? ", …" : ""} with no sea beside ${stayedBehind.length === 1 && stayedBehind[0].stayed.length === 1 ? "it" : "them"}: the province the naval base went to holds its own, and HOI4 refuses ${stayedBehind.length === 1 && stayedBehind[0].stayed.length === 1 ? "it" : "them"} where ${stayedBehind.length === 1 && stayedBehind[0].stayed.length === 1 ? "it stands" : "they stand"}`);
        // (⛔ #a-carry-says-what-it-overfills — one line per taker, whichever carries filled it; ⛔ #a-state-over-its-slots-is-raised-to-a-category-that-holds-them —
        // a taker the same click then raised to a category that holds them is said by that step instead)
        const so = (fr.fixes && fr.fixes.slotOverflow) || {};
        const soRaised = new Set((Array.isArray(so.raised) ? so.raised : []).map((r) => Number(r.stateId)));
        const overfull = [...new Map(nncCarried.filter((c) => c.overSlots && !soRaised.has(Number(c.to))).map((c) => [c.to, c])).values()];
        if (overfull.length) unfinished.push(`left ${overfull.slice(0, 6).map((c) => `state ${c.to} with ${c.overSlots.shared} civilian factories, military factories and dockyards in the ${c.overSlots.slots} slots of its "${c.overSlots.category}" category`).join(", ")}${overfull.length > 6 ? ", …" : ""}: a carry adds to what a state holds, and Nova drops none of them. HOI4 loads the map, and only a launch started with -debug notes such a state in error.log; lower the counts to fit, or raise the state category`);
        // ⛔ #a-state-over-its-slots-is-raised-to-a-category-that-holds-them — the category it gave each state over its slots (Q5: said), and what no category holds
        if (Array.isArray(so.raised) && so.raised.length) parts.push(`moved ${so.raised.length} state(s) holding more civilian factories, military factories and dockyards than their building slots to the smallest state category with room for them, taking no building away (${so.raised.slice(0, 6).map((r) => `state ${r.stateId}: ${r.from || "no category"} → ${r.to}, ${r.shared} in ${r.slots} slots`).join("; ")}${so.raised.length > 6 ? "; …" : ""})`);
        if (Array.isArray(so.left) && so.left.length) unfinished.push(`left ${so.left.length} state(s) over their building slots that no state category this mod loads has room for (${so.left.slice(0, 6).map((l) => `state ${l.stateId}: ${l.shared} in ${l.slots}${l.error ? ` — ${why(l.error)}` : ""}`).join("; ")}${so.left.length > 6 ? "; …" : ""}): lower the counts in the state panel`);
        if (so.error) unfinished.push(`could not move the states over their building slots to a larger category: ${why(so.error)}`);
        if (nncLeft.length) {
          const lstates = [...new Set(nncLeft.map((l) => l.stateId))];
          unfinished.push(`left ${nncLeft.length} dockyard(s) and naval base(s) with no coast where they are, in state ${lstates.slice(0, 8).join(", ")}${lstates.length > 8 ? ", …" : ""}: ${[...new Set(nncLeft.map((l) => l.why).filter(Boolean))].slice(0, 3).join("; ") || "no coast could take them"}. Nova deletes none of them; HOI4 refuses them and the building never appears (only a launch started with -debug writes "Trying to set invalid state building" or "…province building" to error.log for it) — give the state a coast back, or take them out yourself${nncLeft.some((l) => l.province == null) ? " (a dockyard with the state panel's Dockyard field; Save does not stop for it)" : ""}`);
        }
        for (const f of (Array.isArray(nnc.failed) ? nnc.failed : []).slice(0, 5)) unfinished.push(`could not write state ${f.stateId}'s naval buildings: ${why(f.reason)}`);
        // the error can come from the check or from a write partway through, so it is said without claiming which
        if (nnc.error) unfinished.push(`could not finish moving the dockyards and naval bases left with no coast: ${why(nnc.error)}`);
        if (dc.recolored && dc.recolored.length) parts.push(`gave ${dc.recolored.length} blank/black province(s) a unique colour`);
        if (dc.error) unfinished.push(`could not give the blank or black provinces a unique colour: ${why(dc.error)}`);
        if (slv.provincesRemoved || slv.vpRemoved || slv.navalRemoved) parts.push(`scrubbed land-data off ${(slv.provincesRemoved || 0)} stray sea province(s)`);
        if (slv.error) unfinished.push(`could not scrub the land data off the stray sea provinces: ${why(slv.error)}`);
        // #a-strategic-location-on-water-is-cleared — counted on its own line, not folded into the one above: those states
        // are usually the 216 the province cut refuses outright, so "scrubbed 0 stray sea provinces" is what the modder
        // would otherwise read about a click that did do something for them.
        if (slv.slRemoved) parts.push(`took ${slv.slRemoved} strategic location(s) off a province that is now open sea (HOI4 logs the building as invalid and never applies the extra levels)`);
        // #orphan-building-fixer-unreachable — the land half of the line above. The fixer counts a block as removed only once its file
        // is written, and lists every file it could not write in `writeErrors`, uncapped. (It used to count first and fold a failure
        // into `details`, which it cuts at 80, so a failure past the 80th vanished and the page said "took out" a block that was
        // still on disk — measured by the review: 82 claimed, 81 removed.)
        const ob = (fr.fixes && fr.fixes.orphanBuildings) || {};
        // (⛔ #the-harbour-words-say-what-auto-fix-did, B4-17 — …and which blocks, from `details` ({ state, province, reason }), as the answer names them)
        if (ob.removed) { const where = (ob.details || []).slice(0, 6).map((x) => `province ${x.province} in state ${x.state}${x.reason === "province is water" ? ", now sea" : ""}`); parts.push(`took ${ob.removed} province building block(s) out of state history for a province the state does not hold, or one that is now sea${where.length ? ` (${where.join("; ")}${ob.removed > where.length ? "; …" : ""})` : ""} (HOI4 skips the building; only a launch started with -debug writes "Trying to set province building in state that doesn't own it" to error.log for it)`); }
        for (const d of (ob.writeErrors || []).slice(0, 5)) unfinished.push(`could not rewrite history/states/${d.file}, so its ${d.blocks} building block(s) are still there: ${why(d.error)}`);
        if ((ob.writeErrors || []).length > 5) unfinished.push(`…and ${ob.writeErrors.length - 5} more state file(s) the same`);
        if (ob.error) unfinished.push(`could not look for building blocks left in a state that no longer holds their province: ${why(ob.error)}`);
        const rn = regionRepairNote(ro);
        parts.push(...rn.parts);
        if (ca.count) parts.push(`set a category on ${ca.count} state(s)`);
        if (ca.error) unfinished.push(`could not set a category on the states with none: ${why(ca.error)}`);
        // state_no_manpower — a land state with no people, given some.
        const nmp = (fr.fixes && fr.fixes.noManpower) || {};
        if (nmp.fixed) parts.push(`gave ${nmp.fixed} land state(s) with no people a manpower of their own${(nmp.details || []).length ? ` (state ${nmp.details.slice(0, 8).map((d) => d.state).join(", ")}${nmp.fixed > 8 ? ", …" : ""})` : ""} — HOI4 warns "State has no people living in it"`);
        if (nmp.error) unfinished.push(`could not give people to the land states with none: ${why(nmp.error)}`);
        if (co.count) parts.push(`set a continent on ${co.count} province(s)`);
        if (co.error) unfinished.push(`could not set a continent on the provinces with none: ${why(co.error)}`);
        parts.push(...capitalRepairNote(cap).parts);
        if (cap.error) unfinished.push(`could not move the capitals that stand on land their country does not own: ${why(cap.error)}`);
        // #a-dead-state-scope-runs-as-an-effect — name the files, and say plainly that some of them are now the
        // modder's. Copying a base-game country file in is the one thing this click does that the modder cannot
        // see by looking at the map, and it is irreversible by any other Nova button.
        const dss = (fr.fixes && fr.fixes.deadStateScopes) || {};
        if (dss.fixed) parts.push(`commented out ${dss.fixed} effect(s) in country history scoped to a state this map no longer has (HOI4 runs a country's history as the game starts and crashes on one)`
          + ((dss.materialised || []).length
            ? ` — to do it, ${(dss.materialised || []).length} base-game country file(s) are now YOUR mod's, frozen at this build of the game: ${(dss.materialised || []).join(", ")}`
            : ""));
        for (const s of (dss.skipped || [])) unfinished.push(`could not repair ${s.file}${s.stateId ? ` (state ${s.stateId})` : ""}: ${s.reason}`);
        if (dss.error) unfinished.push(`could not comment out the country-history effects scoped to a state this map no longer has: ${why(dss.error)}`);
        // #a-dead-ai-strategy-state-is-silently-discarded — the AI's half, and it copies files in the same way, so
        // it names them in the same way. Every shipping total conversion owns common/ai_strategy; this is how a
        // Nova world comes to own the part of it that its own map broke.
        const das = (fr.fixes && fr.fixes.deadAiStrategies) || {};
        if (das.fixed) parts.push(`commented out ${das.fixed} AI strategy/strategies aimed at a state this map no longer has (HOI4 already discards them, and the AI plays without them)`
          + ((das.materialised || []).length
            ? ` — to do it, ${(das.materialised || []).length} base-game common/ai_strategy file(s) are now YOUR mod's, frozen at this build of the game: ${(das.materialised || []).join(", ")}`
            : ""));
        for (const s of (das.skipped || [])) unfinished.push(`could not repair common/ai_strategy/${s.file}: ${s.reason}`);
        if (das.error) unfinished.push(`could not comment out the AI strategies aimed at a state this map no longer has: ${why(das.error)}`);
        // #a-state-list-in-an-ai-strategy-is-never-checked — the list form, which is the one that crashed; same files, same naming.
        const dal = (fr.fixes && fr.fixes.deadAiStrategyLists) || {};
        if (dal.fixed) parts.push(`took ${dal.fixed} missing state(s) out of AI strategy state lists (HOI4 loads those lists unchecked and crashed on the first AI tick reading one)`
          + (dal.blocks ? `, commenting out ${dal.blocks} strategy/strategies left with no state at all` : "")
          + ((dal.materialised || []).length
            ? ` — to do it, ${(dal.materialised || []).length} base-game common/ai_strategy file(s) are now YOUR mod's, frozen at this build of the game: ${(dal.materialised || []).join(", ")}`
            : ""));
        for (const s of (dal.skipped || [])) unfinished.push(`could not repair common/ai_strategy/${s.file}: ${s.reason}`);
        if (dal.error) unfinished.push(`could not take the missing states out of the AI strategy state lists: ${why(dal.error)}`);
        // #a-script-touches-a-state-that-is-gone — the rest of the base game's script. It can copy a hundred files in, so it
        // says how many and names the first few, and says plainly what it did to each kind.
        // 🌊 #the-supply-queue-counts-naval-links — say how many regions were added and why, in one line.
        const nrq = (fr.fixes && fr.fixes.navalRegionQueue) || {};
        if (nrq.added) parts.push(`added ${nrq.added} empty strategic regions so HOI4's supply system has room for your seas (it needed ${nrq.queue} slots and had ${nrq.n}; now ${nrq.newN}) — nothing on the map moved`);
        for (const e of (nrq.errors || []).slice(0, 3)) unfinished.push(`could not add strategic region ${e.id}: ${e.reason}`);
        if (nrq.error) unfinished.push(`could not make room in the supply system's region list: ${nrq.error}`);
        // 🏝 #a-drowned-coast-shows-through-the-sea — the old coast left at beach height under the sea, and every file the
        // settle rewrote with it. On a world built before the fix this is often the ONLY thing the click did (review of
        // 620258f: TEST 29's Auto-fix changed nine files through this step and the summary said nothing).
        const dco = (fr.fixes && fr.fixes.drownedCoast) || {};
        if (dco.changed) {
          const files = [dco.file || "map/heightmap.bmp", dco.terrain && dco.terrain.changed ? "map/terrain.bmp" : "", dco.trees && dco.trees.changed ? "map/trees.bmp" : "",
            dco.normal && dco.normal.changed ? "map/world_normal.bmp" : "", ...Object.keys((dco.textures && dco.textures.files) || {}).map((n) => "map/terrain/" + n),
            // the sixth picture, and the files of the models the lowered ground carried (review of add0eb0 / 6a1fd27)
            dco.minimap && dco.minimap.changed ? "gfx/minimap/minimap.dds" : "",
            // …and the rivers that ran over the settled land (#erased-land-takes-its-rivers): the settle is a sink like the erase
            dco.rivers && dco.rivers.changed ? "map/rivers.bmp" : "",
            ...(dco.models && dco.models.changed ? Object.keys(dco.models.files || {}).map((f) => "map/" + f) : [])].filter(Boolean);
          parts.push(`lowered ${Number(dco.pixels || 0).toLocaleString()} pixels of old coastline left at beach height under your sea — the sandy "islands" along the sea's borders (rewrote ${files.join(", ")})`
            + (dco.leftAlone ? `; ${dco.leftAlone} province(s) whose sea floor was shaped by hand were left alone` : ""));
        }
        if (dco.error) unfinished.push(`could not settle the old coastline under your sea: ${why(dco.error)}`);
        // 🎨 #the-air-map-still-shows-the-old-world — the five colour pictures, named, because the mod may have just taken
        // its own copies of them.
        const wtx = (fr.fixes && fr.fixes.worldTextures) || {};
        if (wtx.changed) {
          const names = Object.keys(wtx.files || {}), copied = names.filter((n) => wtx.files[n] && wtx.files[n].materialized);
          parts.push(`repainted your map's colour pictures, which still showed the map below yours on ${Math.round(100 * (wtx.share || 0))}% of it (${names.map((n) => "map/terrain/" + n).join(", ")})`
            + (copied.length ? ` — your mod now has its own copy of ${copied.length === names.length ? "each" : copied.length + " of them"}` : ""));
        }
        if (wtx.error) unfinished.push(`could not repaint your map's colour pictures: ${why(wtx.error)}`);
        // 🗺 #the-minimap-still-shows-the-earth — the minimap tab, repainted on its own answer
        const mmp = (fr.fixes && fr.fixes.minimap) || {};
        if (mmp.changed) parts.push(`repainted your minimap, which still showed the map below yours on ${Math.round(100 * (mmp.share || 0))}% of it (${mmp.texels} of its points, gfx/minimap/minimap.dds)`
          + (mmp.materialized ? " — your mod now has its own copy" : ""));
        if (mmp.error) unfinished.push(`could not repaint your minimap: ${why(mmp.error)}`);
        // 🎨 #the-tint-boxes-still-sit-on-the-old-world — the colour-grading boxes, named, since a modder may know them by name
        const pfx = (fr.fixes && fr.fixes.posteffect) || {};
        if (pfx.changed) {
          const named = (pfx.boxes || []).filter(Boolean);
          parts.push(`took out ${pfx.removed} colour-grading box${pfx.removed === 1 ? "" : "es"} that sat over ground your map changed${named.length ? ` (${named.slice(0, 8).join(", ")}${named.length > 8 ? ", …" : ""})` : ""}, in gfx/posteffect_volumes.txt`
            + (pfx.kept ? `; ${pfx.kept} still over their own ground stay` : "") + (pfx.materialized ? " — your mod now has its own copy" : ""));
        }
        if (pfx.error) unfinished.push(`could not take out the colour-grading boxes placed for another map: ${why(pfx.error)}`);
        // 🧱 #a-world-keeps-the-base-games-state-ids — the biggest single change a click can make to a world, so said first and plainly.
        const sif = (fr.fixes && fr.fixes.stateIdFloor) || {};
        if (sif.added) parts.push(`split ${sif.added} of your ${sif.fromItsCountry ? "" : "largest "}states so your world has every state id the base game's scripts name (now ${sif.states} states, up to ${sif.ceiling})`
          // ⛔ #an-id-the-scripts-name-goes-back-to-its-country — how many were cut from the country that held the id below
          + (sif.fromItsCountry ? `, ${sif.fromItsCountry === sif.added ? "each" : `${sif.fromItsCountry} of them`} cut from the country that held that id in the world below, so the scripts naming it act on that country's land${sif.fromItsCountry === sif.added ? "" : ", the rest from your largest states"}` : "")
          + ` — each new state keeps its parent's owner, cores and claims`
          + (sif.victoryPoints ? `, every victory point stays in the state it was in, and ${sif.victoryPoints} new state(s) got one of their own` : "")
          // #a-split-state-is-furnished-like-its-parent — the air bases a parent's gave, and apart (#an-air-base-holds-the-planes-it-starts-with)
          // those a base-less parent's child got because an order of battle bases wings in its id: not "as the state they came from has"
          + ((sif.airBases || 0) - (sif.airBasesAsked || 0) > 0 ? `, and ${sif.airBases - (sif.airBasesAsked || 0)} new state(s) got an air base, as the state they came from has` : "")
          + (sif.airBasesAsked ? `, and ${sif.airBasesAsked} new state(s) got one though the state they came from has none, because an order of battle bases air wings in it` : "")
          + (sif.stoppedShort ? `; ${sif.stoppedShort} id(s) are still missing because no state had land left to split` : ""));
        for (const e of (sif.errors || []).slice(0, 5)) unfinished.push(`could not split state ${e.state}: ${e.reason}`);
        // ⛔ #a-split-keeps-its-victory-point — a new state whose victory point could not be written, named
        for (const e of (sif.vpErrors || []).slice(0, 5)) unfinished.push(`new state ${e.state} was made, but ${e.reason}`);
        if (sif.error) unfinished.push(`could not split states to give your world every state id the base game's scripts name: ${why(sif.error)}`);
        // the names the split's new states were given, when some could not be written (review of e1f3586, finding 1)
        const sifNames = sif.stateNames || {};
        if (sifNames.error) unfinished.push(`the new states were made, but their names could not be written to localisation: ${why(sifNames.error)}`);
        else if (sifNames.note) unfinished.push(sifNames.note);
        // ⚓ #a-strait-left-on-land — name the rules, because the modder saw the icon and will look for it.
        const rol = (fr.fixes && fr.fixes.rulesOnLand) || {};
        // ⚓ #a-strait-nobody-can-hold — …and the two kinds by name, since one reads as sea gone and the other as land gone
        const rolK = rol.byKind || { sea: rol.rules || [], land: [] };
        if (rol.fixed) parts.push(`took out ${rol.fixed} base-game strait rule(s): `
          + [(rolK.sea || []).length ? `${rolK.sea.length} whose sea is land in this map (${rolK.sea.join(", ")})` : "",
            (rolK.land || []).length ? `${rolK.land.length} that no country could hold any more because none of their land is left (${rolK.land.join(", ")})` : ""].filter(Boolean).join("; ")
          + ` — their crossings stay as plain links`
          + ((rol.materialised || []).length ? ` — to do it, ${(rol.materialised || []).join(" and ")} ${(rol.materialised || []).length === 1 ? "is" : "are"} now YOUR mod's` : ""));
        for (const s of (rol.skipped || [])) unfinished.push(`could not repair ${s.file}${s.rule ? ` (${s.rule})` : ""}: ${s.reason}`);
        if (rol.error) unfinished.push(`could not take out the base-game strait rules your map left on land: ${why(rol.error)}`);
        // ⛔ #an-adjacency-name-is-encoded-twice — name a few, because the modder will look for them in the file.
        const anm = (fr.fixes && fr.fixes.adjacencyNames) || {};
        if (anm.fixed) parts.push(`put back ${anm.fixed} name(s) in map/adjacencies.csv that an older Auto-fix had encoded twice (${(anm.names || []).slice(0, 4).join(", ")}${anm.fixed > 4 ? ", …" : ""}) — only the names changed`);
        if (anm.error) unfinished.push(`could not put back the garbled names in map/adjacencies.csv: ${why(anm.error)}`);
        const dsr = (fr.fixes && fr.fixes.deadScriptStateRefs) || {};
        if (dsr.fixed) {
          const k = dsr.byKind || {};
          const kinds = [k.effect && `commented out ${k.effect} action(s) on a missing state`, k.check && `made ${k.check} unchecked condition(s) on one "always = no"`,
            k.read && `neutralised ${k.read} value(s) read off one`, k.targets && `took ${k.targets} missing state(s) out of targeted decisions`].filter(Boolean);
          const mat = dsr.materialised || [];
          parts.push(`${kinds.join(", ")} in focuses, decisions and events (these are the references HOI4 does not check first)`
            + (mat.length ? ` — to do it, ${mat.length} base-game script file(s) are now YOUR mod's, frozen at this build of the game: ${mat.slice(0, 8).join(", ")}${mat.length > 8 ? `, and ${mat.length - 8} more` : ""}` : ""));
        }
        for (const s of (dsr.skipped || [])) unfinished.push(`could not repair ${s.file}${s.line ? ` line ${s.line}` : ""}: ${s.reason}`);
        if (dsr.error) unfinished.push(`could not repair the focuses, decisions and events that name a state this map no longer has: ${why(dsr.error)}`);
        // #an-order-of-battle-under-water — say how many, and say plainly that the inherited ones were left,
