        const dd = (fr.fixes && fr.fixes.drownedDivisions) || {};
        // ⛔ #a-copied-order-of-battle-names-its-layer (tool campaign B2-33) — the order-of-battle files a repair copied in come from the layer below, which
        // on an add-on is the mod it is built on: Millennium Dawn's ENG_2000_bba.txt was called a "base-game" file, "frozen at this build of the game",
        // where what stops reaching it is that mod's next update. The answer names the files only, so the line says "base-game" only when the mod
        // depends on nothing (the model's dependencyRoots); otherwise it names both layers it can be. (`typeof`: tests lift the summary on its own.)
        const oobCopied = (files) => {
          const n = files.length, list = `${files.slice(0, 8).join(", ")}${n > 8 ? `, and ${n - 8} more` : ""}`;
          const onlyGame = typeof model !== "undefined" && model && Array.isArray(model.dependencyRoots) && model.dependencyRoots.length === 0;
          return onlyGame ? ` — to do it, ${n} base-game order-of-battle file(s) are now YOUR mod's, frozen at this build of the game: ${list}`
            : ` — to do it, ${n} order-of-battle file(s) your mod inherited (from the base game, or from a mod it is built on) are now YOUR mod's, as they stand: a later update of the game or of that mod no longer reaches them: ${list}`;
        };
        if (dd.moved) parts.push(`moved ${dd.moved} division(s) out of the water onto the nearest land their own country owns`
          + ((dd.files || []).length ? ` across ${(dd.files || []).length} order-of-battle file(s)` : "")
          + ((dd.materialised || []).length ? oobCopied(dd.materialised) : ""));
        if (dd.noLand) parts.push(`${dd.noLand} division(s) could not be moved: their country owns no land on this map`);
        // ⛔ #a-script-loads-an-army-later — the armies the game's events and focuses load mid-game, said apart: they go to the
        // land of the country that held their province below, which is not always one that owns land here.
        const ddl = dd.later || {};
        if (ddl.moved) parts.push(`${ddl.moved} of those divisions are in order-of-battle files the game's events or focuses load later, and went to the nearest land of the country that held their province in the world your map replaced`);
        if (ddl.noLand) parts.push(`${ddl.noLand} division(s) the game's events or focuses load later could not be moved: the country that held their land below owns none on this map`);
        for (const s of (dd.skipped || [])) unfinished.push(`could not move the divisions in history/units/${s.file}: ${s.reason}`);
        if (dd.error) unfinished.push(`could not move the divisions out of the water: ${why(dd.error)}`);
        // ⚓ #a-fleet-berthed-where-the-map-took-the-land-away — name the files it copied in, and say plainly how many
        // it could NOT re-berth, because those are the ones that crash: every minidump at this address names a fleet
        // on LAND with no sea beside it, while fleets at sea load fine. The modder has to know the click did not finish.
        const fb = (fr.fixes && fr.fixes.fleetBerths) || {};
        const fbCopied = (fb.materialised || []).length ? oobCopied(fb.materialised) : "";
        if (fb.moved || (fb.rebased && fb.toSea)) parts.push(`re-berthed ${fb.moved || 0} task force(s)${fb.rebased ? ` and ${fb.rebased} fleet home base(s)` : ""} at the nearest harbour their own country owns (HOI4 has crashed while loading on a fleet whose port had no sea left)` + fbCopied);
        // ⛔ #a-fleets-home-port-the-map-landlocked — a click that moved only home ports says so, with no crash claim: none has been
        // tied to a home port, every one named a task force's location.
        else if (fb.rebased) parts.push(`moved ${fb.rebased} fleet home base(s) off land the map cut off from the sea to the nearest harbour their own country owns` + fbCopied);
        // ⚓ #a-coastless-navy-goes-to-sea — a country with no coast left had nowhere to go; its fleets now go to sea.
        if (fb.toSea) parts.push(`moved ${fb.toSea} task force(s) of countries with no coast left to the nearest sea, with their home bases — a fleet at sea loads, a fleet on land with no sea beside it has crashed every Nova-built world that had one. No ship was removed`);
        // Split by what the stranded fleet is standing on, because the two are not the same risk: a fleet at sea
