        // …and only a network with hubs is called one: railways written without their hubs are said as railways alone
        if (snw.changed && snw.hubs) parts.push(`gave your world the supply network it had none of: ${snw.hubs} supply hub(s)${snw.railways ? ` and ${snw.railways} railway(s) joining them` : ""}, written to map/supply_nodes.txt${snw.railways ? " and map/railways.txt" : ""}`);
        else if (snw.changed && snw.railways) parts.push(`wrote ${snw.railways} railway(s) to map/railways.txt`);
        if (snw.error) unfinished.push(`could not ${snw.changed ? "finish" : "write"} your world's supply network: ${why(snw.error)}`);
