        if (chb.hubs) parts.push(`gave the ${chb.hubs} capital(s) it moved a supply hub${chb.railways ? ` and ${chb.railways} railway(s) joining ${chb.hubs === 1 ? "it" : "them"} to ${chb.hubs === 1 ? "its" : "their"} country's network` : ""} (${(chb.states || []).map((s) => `${s.tag}: state ${s.state}`).join(", ")})`);
