        for (const s of (Array.isArray(chb.skipped) ? chb.skipped : [])) unfinished.push(`could not give ${s.tag}'s moved capital a supply hub: ${why(s.reason)}`);
        if (chb.error) unfinished.push(`could not give the capitals it moved a supply hub: ${why(chb.error)}`);
        // ⛔ #a-railway-gap-is-split-where-the-game-drops-it (B4-7) — each split named: the railway, the link the game drops, what is left
        const rgp = (fr.fixes && fr.fixes.railGaps) || {};
        if (rgp.fixed) {
          const ss = Array.isArray(rgp.splits) ? rgp.splits : [];
          const one = (s) => `${s.from} → ${s.to} (line ${s.line}, level ${s.level}: ${s.removed ? "nothing of 2 provinces was left, so the railway is gone" : `${(s.pieces || []).length} piece(s) kept`})`;
          parts.push(`split ${rgp.fixed} railway link(s) between provinces that do not touch, which HOI4 drops and carries no supply over, keeping every piece of 2 or more provinces: ${ss.slice(0, 6).map(one).join("; ")}${ss.length > 6 ? "; …" : ""}` + materialisedNote(rgp.materialised));   // #an-add-on-is-told-what-auto-fix-froze: the split copies railways.txt in when the mod had none
        }
        if (rgp.error) unfinished.push(`could not split the railway links between provinces that do not touch: ${why(rgp.error)}`);
        // ⛔ #a-capital-state-keeps-a-victory-point — the capital states it gave a victory point, where HOI4 stands a capital, and any it could not
        const cvp = (fr.fixes && fr.fixes.capitalVictoryPoints) || {};
        if (cvp.fixed) parts.push(`gave ${cvp.fixed} capital state(s) with no victory point one, since HOI4 stands a capital on its state's best victory point and otherwise on its first province (${(cvp.given || []).slice(0, 8).map((g) => `${g.tag}: state ${g.state}, province ${g.province}`).join("; ")}${(cvp.given || []).length > 8 ? "; …" : ""})`);
        if (cvp.unnamedNote) parts.push(cvp.unnamedNote.replace(/\.$/, ""));
