        if (cvp.error) unfinished.push(`could not give capital states a victory point: ${why(cvp.error)}`);
        // ⛔ #a-lake-made-sea-goes-back-to-a-lake — a cut-off sea that was a lake is made that lake again, and said apart from the land
        const iseaLakes = (isea.details || []).filter((d) => d.lake), iseaLand = (Number(isea.fixed) || 0) - (Number(isea.lakes) || 0);
        if (Number(isea.lakes) > 0) parts.push(`made ${isea.lakes} cut-off sea province(s) the lake they were (${iseaLakes.slice(0, 8).map((d) => d.province).join(", ")}${iseaLakes.length > 8 ? ", …" : ""}): a lake inland is what the game ships, a sea cut off from the ocean is not; set the type again in 🔍 Inspect if you meant something else`);
        if (iseaLand > 0) parts.push(`turned ${iseaLand} isolated inland-sea province(s) into land`);
        if (isea.error) unfinished.push(`could not repair the isolated inland-sea provinces: ${why(isea.error)}`);
        // ⛔ #a-lone-sea-nobody-uses — what the warning offered: which seas, how big, and why
        const lone = (fr.fixes && fr.fixes.loneSeas) || {};
        const loneLakes = (lone.details || []).filter((d) => d.lake), loneLand = (lone.details || []).filter((d) => !d.lake);
        if (loneLakes.length) parts.push(`made ${loneLakes.length === 1 ? "sea" : "seas"} ${loneLakes.slice(0, 8).map((d) => d.province).join(", ")}${loneLakes.length > 8 ? ", …" : ""} the lake${loneLakes.length === 1 ? "" : "s"} ${loneLakes.length === 1 ? "it was" : "they were"} (${loneLakes.reduce((n, d) => n + (d.pixels || 0), 0).toLocaleString("en-US")} px), with no other sea beside ${loneLakes.length === 1 ? "it" : "them"}; set the type again in 🔍 Inspect if you meant something else`);
